(function(E){ const x = E["int-m1"] = E["int-m1"] || {units:{}}; x.units["int-3"] = {"grammar":{"id":"c-int-3-g","level":"B1","course":"interview","unit":"int-3","title":"Feelings: -ed or -ing (bored or boring)","titleTr":"Duygular: -ed mi, -ing mi (bored mu, boring mi)","titleFa":"احساس‌ها: ‎-ed یا ‎-ing (bored یا boring)","formsTable":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["A person feels it: -ed","I was embarrassed. I am interested in this role."],["A thing causes it: -ing","The question was embarrassing. The role is interesting."],["Common pairs","bored / boring, tired / tiring, confused / confusing, excited / exciting"]]},"wrong":"I am very interesting in this position.","right":"I am very interested in this position.","blank":{"sentence":"The night shifts were long and ___, but I never missed a day.","word":"tiring","distractors":["tired","tire"]},"wrong2":"After the interview I felt very exciting.","right2":"After the interview I felt very excited.","blank2":{"sentence":"I was a little ___ by the first question, so I asked her to repeat it.","word":"confused","distractors":["confusing","confuse"]},"expParts":{"rule":[{"en":"-ed: how a person feels.","tr":"-ed: kişinin nasıl hissettiği.","fa":"پسوند ed حسی را نشان می‌دهد که یک آدم دارد.","ex":"I was nervous and a bit confused."},{"en":"-ing: the thing that causes the feeling.","tr":"-ing: duyguya sebep olan şey.","fa":"پسوند ing چیزی را نشان می‌دهد که آن حس را ایجاد می‌کند.","ex":"The question was confusing."},{"en":"\"I'm interesting\" praises you. In an interview, say interested in + the thing you like.","tr":"\"I'm interesting\" kendini övmek olur. Mülakatta interested in + ilgilendiğin şey de.","fa":"جمله‌ی «I'm interesting» یعنی از خودت تعریف می‌کنی. در مصاحبه بگو «I'm interested in» و بعد چیزی را بیاور که به آن علاقه داری.","ex":"I am interested in this role."}],"test":{"en":"Is it someone's feeling? -ed. Is it the cause of the feeling? -ing.","tr":"Birinin duygusu mu? -ed. Duygunun sebebi mi? -ing.","fa":"احساسِ کسی است؟ ‎-ed. علتِ آن احساس است؟ ‎-ing."},"contrast":{"en":"Turkish uses two different words (sıkıldım / sıkıcı), and so does Persian (حوصله‌ام سر رفت / کسل‌کننده). English changes only the ending, so the endings get mixed.","tr":"Türkçede iki ayrı kelime vardır (sıkıldım / sıkıcı). İngilizcede sadece son ek değişir (bored / boring), bu yüzden karışır.","fa":"در فارسی دو عبارت جدا داریم (حوصله‌ام سر رفت / کسل‌کننده). در انگلیسی فقط پسوند عوض می‌شود (bored / boring) و برای همین این دو را با هم اشتباه می‌گیریم."}},"errorWatch":[{"find":["i am interesting in","i'm interesting in","i am very interesting in","i'm very interesting in","i was interesting in","i am really interesting in"],"fix":{"en":"For your own feeling, use -ed: 'I am interested in this position.'","tr":"Kendi duygun için -ed kullan: 'I am interested in this position.'","fa":"برای حس خودت از ‎-ed استفاده کن: «I am interested in this position.‎»"}},{"find":["i felt very exciting","i felt exciting","i am exciting about","i'm exciting about","i was very exciting","i was so embarrassing","i felt embarrassing","i am confusing about","i was confusing about","i felt boring"],"fix":{"en":"A person's feeling takes -ed: 'I felt excited', 'I was embarrassed'.","tr":"Bir kişinin duygusu -ed alır: 'I felt excited', 'I was embarrassed'.","fa":"حس یک آدم با ‎-ed می‌آید: «I felt excited»، «I was embarrassed»."}}]},"b2":{"id":"c-int-3-b2","level":"B2","track":"B2","course":"interview","unit":"int-3","title":"Keeping small talk going: question tags","titleTr":"Sohbeti sürdürmek: onay soruları (question tags)","titleFa":"ادامه دادن گپ: question tag","formsTable":{"headers":{"en":["Statement","Tag"],"tr":["Cümle","Ek"],"fa":["جمله","tag"]},"rows":[["Positive statement, negative tag","It's a nice building, isn't it?"],["Negative statement, positive tag","You aren't from Istanbul, are you?"],["No helper verb: do / does / did","You found the office, didn't you?"]]},"wrong":"It's a nice building, is not it?","right":"It's a nice building, isn't it?","blank":{"sentence":"You came by metro, ___?","word":"didn't you","distractors":["weren't you","don't you"]},"wrong2":"You haven't been to Tehran, haven't you?","right2":"You haven't been to Tehran, have you?","blank2":{"sentence":"It's your first time in this building, ___?","word":"isn't it","distractors":["wasn't it","doesn't it"]},"useIn":{"en":"B2: in the small talk, use one question tag to keep the conversation going.","tr":"B2: küçük sohbette konuşmayı sürdürmek için bir question tag kullan.","fa":"در مسیر B2: در گپ کوتاه، برای ادامه دادن حرف یک question tag به کار ببر."},"exitItem":{"from":"int-3","kind":"blank","prompt":"Your manager works with the Ankara team, ___?","options":["doesn't she","isn't she","didn't she"],"correct":0},"expParts":{"rule":[{"en":"Use the helper verb from the statement.","tr":"Cümledeki yardımcı fiili kullan.","fa":"فعل کمکیِ جمله را به کار ببر.","ex":"It's hot today, isn't it?"},{"en":"Positive statement, negative tag, and the other way round.","tr":"Olumlu cümle, olumsuz ek; tersi de geçerli.","fa":"اگر جمله مثبت باشد tag منفی می‌آید و برعکس.","ex":"You aren't from Istanbul, are you?"},{"en":"No helper verb? Use do, does or did.","tr":"Yardımcı fiil yok mu? do, does ya da did kullan.","fa":"فعل کمکی نیست؟ از do، does یا did استفاده کن.","ex":"You found us easily, didn't you?"}],"test":{"en":"Find the helper verb. Flip positive to negative. If there is no helper verb, use do, does or did.","tr":"Yardımcı fiili bul. Olumluyu olumsuza çevir. Yardımcı fiil yoksa do, does ya da did kullan.","fa":"فعل کمکی را پیدا کن. مثبت را منفی کن. اگر فعل کمکی نیست، do، does یا did بیاور."},"contrast":{"en":"Turkish 'değil mi?' and Persian 'مگر نه؟' never change. English tags change with the verb: isn't it, didn't you, are you.","tr":"Türkçedeki 'değil mi?' hiç değişmez. İngilizcede ek fiile göre değişir: isn't it, didn't you, are you.","fa":"«مگر نه؟» در فارسی هیچ‌وقت عوض نمی‌شود. tag انگلیسی با فعل عوض می‌شود: isn't it، didn't you، are you."}},"errorWatch":[{"find":["is not it","are not you","do not you","did not you","was not it","have not you","does not it"],"fix":{"en":"In a tag, use the short form: 'isn't it?', 'didn't you?'","tr":"Onay sorusunda kısa biçimi kullan: 'isn't it?', 'didn't you?'","fa":"در tag شکل کوتاه را بیاور: «isn't it?‎»، «didn't you?‎»"}}]},"vocab":{"id":"c-int-3-v","level":"B1","category":"vocab","course":"interview","unit":"int-3","goals":["career"],"title":{"en":"The First Five Minutes","tr":"İlk Beş Dakika","fa":"پنج دقیقه‌ی اول"},"cards":[{"word":"small talk","sentence":"A little small talk helps both people relax.","meaning":{"en":"Light, friendly conversation about easy topics.","tr":"havadan sudan sohbet.","fa":"گپ کوتاه و دوستانه درباره‌ی موضوع‌های ساده"}},{"word":"reception","sentence":"Please wait at reception until someone comes down.","meaning":{"en":"The desk near the entrance where visitors are welcomed.","tr":"resepsiyon, danışma.","fa":"پذیرش؛ میز ورودی"}},{"word":"first impression","sentence":"You only get one chance to make a good first impression.","meaning":{"en":"What people think of you when they first meet you.","tr":"ilk izlenim.","fa":"اولین برداشت؛ تأثیر اول"}},{"word":"nervous","sentence":"It's normal to feel nervous before an interview.","meaning":{"en":"Worried and a little afraid.","tr":"gergin, heyecanlı.","fa":"مضطرب؛ نگران"}},{"word":"confident","sentence":"She sounded calm and confident in the second round.","meaning":{"en":"Sure that you can do something well.","tr":"kendinden emin.","fa":"مطمئن به خود؛ با اعتمادبه‌نفس"}},{"word":"handshake","sentence":"He gave the interviewer a short, firm handshake.","meaning":{"en":"Shaking hands when you meet someone.","tr":"tokalaşma.","fa":"دست دادن"}},{"word":"on time","sentence":"Arrive on time, or ten minutes early.","meaning":{"en":"At the right time, not late.","tr":"zamanında.","fa":"سر وقت"}},{"word":"Did you find us okay?","sentence":"\"Did you find us okay?\" \"Yes, thanks. The map was very clear.\"","meaning":{"en":"A friendly question about your journey to the office.","tr":"\"Bizi kolay buldunuz mu?\" (yolculuk hakkında samimi bir soru).","fa":"سؤالی دوستانه درباره‌ی راه آمدنت: «راحت پیدایمان کردید؟»"}},{"word":"values","sentence":"Read the company's values on its website before you go.","meaning":{"en":"The ideas a company says are most important to it.","tr":"değerler","fa":"ارزش‌ها"}},{"word":"I read that","sentence":"I read that you opened a new office in Izmir last year.","meaning":{"en":"Shows that you did some research.","tr":"Araştırma yaptığını gösterir.","fa":"نشان می‌دهد تحقیق کرده‌ای."}}]},"judge":{"id":"c-int-3-j","course":"interview","unit":"int-3","type":"judge","title":{"en":"Why us?","tr":"Neden biz?","fa":"چرا ما؟"},"prompt":"Five answers to \"Why do you want to work here?\", from five different people.","parts":["A real fact about the company","A link to your own experience","What you would bring"],"instruction":{"en":"Tap what each answer has. The strongest answer has all three.","tr":"Her cevapta ne olduğuna dokun. En güçlü cevapta üçü de vardır.","fa":"روی چیزهایی که هر جواب دارد بزن. قوی‌ترین جواب هر سه را دارد."},"items":[{"by":"AI tool","answer":"I have long admired your company's commitment to excellence and innovation, and I would be honoured to join your dynamic team.","present":[],"fix":{"en":"This fits every company in the world. Find one fact on their website or in the news, and start there.","tr":"Bu, dünyadaki her şirkete uyar. Web sitelerinde ya da haberlerde tek bir gerçek bul ve oradan başla.","fa":"این را درباره‌ی همه‌ی شرکت‌های دنیا می‌شود گفت. یک واقعیت از سایتشان یا خبرها پیدا کن و از همان‌جا شروع کن."}},{"by":"Teacher","answer":"Your website says you opened three new schools this year.","present":["A real fact about the company"],"fix":{"en":"Good research, but it stops there. Add the link: \"I helped open a school in 2023, so I know what the first year needs.\"","tr":"İyi araştırma, ama orada bitiyor. Bağlantıyı ekle: \"I helped open a school in 2023, so I know what the first year needs.\"","fa":"تحقیق خوبی است، ولی همان‌جا تمام می‌شود. ربطش را اضافه کن: «I helped open a school in 2023, so I know what the first year needs.»"}},{"by":"Software tester","answer":"You are close to my home, and I heard the salary is good.","present":[],"fix":{"en":"These are reasons for you, not for them. Talk about their work and what you could do there.","tr":"Bunlar senin için nedenler, onlar için değil. Onların işinden ve orada neler yapabileceğinden bahset.","fa":"این‌ها دلیل‌های خودت است، نه دلیل آن‌ها. از کار خودشان و کاری که می‌توانی آنجا بکنی حرف بزن."}},{"by":"Receptionist","answer":"I have handled guest complaints in English for five years, so I could solve your customers' problems quickly.","present":["A link to your own experience","What you would bring"],"fix":{"en":"Strong, but it could be any company. Add a fact first: \"I read that most of your customers are in Europe.\"","tr":"Güçlü, ama herhangi bir şirket için olabilir. Önce bir gerçek ekle: \"I read that most of your customers are in Europe.\"","fa":"قوی است، ولی برای هر شرکتی می‌شود گفت. اول یک واقعیت اضافه کن: «I read that most of your customers are in Europe.»"}},{"by":"Good model","answer":"I read that you are growing your support team in Germany. I have worked with German customers for four years, so I could help new staff learn what these customers expect.","present":["A real fact about the company","A link to your own experience","What you would bring"],"fix":null}]},"speaking":{"id":"int-3","course":"interview","unit":"int-3","topic":{"en":"Small talk, then \"Why us?\"","tr":"Küçük sohbet, sonra \"Neden biz?\"","fa":"گپ کوتاه، بعد «چرا ما؟»"},"warmup":{"en":"Open the website of a company you like. Find one fact you could mention in an interview. No ad yet? Use this one: Customer Support Specialist at an online travel company (two or more years with customers, good written English, weekend shifts; it now sells trips in six new countries).","tr":"Sevdiğin bir şirketin web sitesini aç. Mülakatta söyleyebileceğin bir gerçek bul. Henüz ilanın yok mu? Bunu kullan: Çevrimiçi bir seyahat şirketinde Customer Support Specialist (müşterilerle en az iki yıl deneyim, iyi yazılı İngilizce, hafta sonu vardiyaları; şirket artık altı yeni ülkede seyahat satıyor).","fa":"سایت شرکتی را که دوست داری باز کن. یک واقعیت پیدا کن که بشود در مصاحبه گفت. هنوز آگهی نداری؟ از این استفاده کن: Customer Support Specialist در یک شرکت سفر اینترنتی (دست‌کم دو سال کار با مشتری، انگلیسی نوشتاری خوب، شیفت آخر هفته؛ این شرکت حالا در شش کشور تازه سفر می‌فروشد)."},"questions":[{"en":"The interviewer meets you: \"Did you find us okay?\" Answer and add one small detail.","tr":"Mülakatı yapan kişi seni karşılıyor: \"Did you find us okay?\" Cevap ver ve küçük bir ayrıntı ekle.","fa":"مصاحبه‌کننده به استقبالت می‌آید: «Did you find us okay?» جواب بده و یک نکته‌ی کوچک اضافه کن."},{"en":"\"Have you been to this part of the city before?\" Answer, and give the question back.","tr":"\"Have you been to this part of the city before?\" Cevap ver ve soruyu ona da sor.","fa":"«Have you been to this part of the city before?» جواب بده و همان سؤال را از او بپرس."},{"en":"\"How are you feeling today?\" Say honestly how you feel, with an -ed word, and one positive thing.","tr":"\"How are you feeling today?\" Nasıl hissettiğini -ed'li bir kelimeyle dürüstçe söyle ve olumlu bir şey ekle.","fa":"«How are you feeling today?» صادقانه با یک کلمه‌ی ‎-ed بگو چه حسی داری و یک چیز مثبت هم بگو."},{"en":"\"So, why do you want to work here?\" Give a fact, a link and what you would bring.","tr":"\"So, why do you want to work here?\" Bir gerçek, bir bağlantı ve katacağın şeyi söyle.","fa":"«So, why do you want to work here?» یک واقعیت، ربطش به خودت و چیزی را که به آن‌ها اضافه می‌کنی بگو."}],"followups":[{"en":"Do the whole five minutes again in 60 seconds, then 45. Keep the small talk light.","tr":"Beş dakikanın tamamını önce 60, sonra 45 saniyede yeniden yap. Küçük sohbeti hafif tut.","fa":"کل این پنج دقیقه را دوباره در ۶۰ و بعد ۴۵ ثانیه انجام بده. گپ کوتاه را سبک نگه دار."}],"expressions":[{"phrase":"Yes, thanks. The ... was...","meaning":{"en":"Answers small talk and adds a detail.","tr":"Küçük sohbete cevap verir ve ayrıntı ekler.","fa":"به گپ کوتاه جواب می‌دهد و جزئیات اضافه می‌کند."}},{"phrase":"How about you?","meaning":{"en":"Gives the question back.","tr":"Soruyu karşı tarafa da sorar.","fa":"همان سؤال را از طرف مقابل می‌پرسد."}},{"phrase":"I read that...","meaning":{"en":"Opens your fact about the company.","tr":"Şirketle ilgili bilgini söylemeye başlar.","fa":"حرفت را با واقعیتی درباره‌ی شرکت شروع می‌کند."}}],"selfCheck":[{"en":"I answered the small talk with one detail, not only \"yes\".","tr":"Küçük sohbete sadece \"yes\" demeden, bir ayrıntıyla cevap verdim.","fa":"به گپ کوتاه فقط با «yes» جواب ندادم و یک نکته گفتم."},{"en":"I gave one question back.","tr":"Ben de bir soru sordum.","fa":"من هم یک سؤال پرسیدم."},{"en":"I said how I feel with an -ed word.","tr":"Nasıl hissettiğimi -ed'li bir kelimeyle söyledim.","fa":"حسم را با یک کلمه‌ی ‎-ed گفتم."},{"en":"My \"Why us?\" had a real fact about this company.","tr":"\"Neden biz?\" cevabımda bu şirketle ilgili gerçek bir bilgi vardı.","fa":"در جواب «چرا ما؟» یک واقعیت درباره‌ی همین شرکت گفتم."}],"model":"Yes, thanks, the map was very clear. No, it's my first time here, but I like this part of the city. How about you? I'm a little nervous, but I'm excited to be here. I read that you're opening an office in Germany. I've supported German clients for four years, so I could help that team from day one."},"writing":{"id":"c-int-3-w","course":"interview","unit":"int-3","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your \"Why us?\" answer","tr":"\"Neden biz?\" cevabın","fa":"جواب تو به «چرا ما؟»"},"portfolio":"int-final-2","prompt":{"en":"Choose a company you want to work for. Find three facts on its website, in the job ad or in the news. Write your answer to \"Why do you want to work here?\" (50-80 words): one real fact, a link to your own experience, and what you would bring. No ad yet? Use this one: Customer Support Specialist at an online travel company (two or more years with customers, good written English, weekend shifts; it now sells trips in six new countries).","tr":"Çalışmak istediğin bir şirket seç. Web sitesinde, iş ilanında ya da haberlerde üç gerçek bul. \"Why do you want to work here?\" sorusuna cevabını yaz (50-80 kelime): gerçek bir bilgi, kendi deneyiminle bağlantısı ve katacağın şey. Henüz ilanın yok mu? Bunu kullan: Çevrimiçi bir seyahat şirketinde Customer Support Specialist (müşterilerle en az iki yıl deneyim, iyi yazılı İngilizce, hafta sonu vardiyaları; şirket artık altı yeni ülkede seyahat satıyor).","fa":"شرکتی را که دوست داری در آن کار کنی انتخاب کن. سه واقعیت از سایتش، آگهی شغلی یا خبرها پیدا کن. جوابت را به «Why do you want to work here?» بنویس (۵۰ تا ۸۰ کلمه): یک واقعیت، ربطش به تجربه‌ی خودت و چیزی که به آن‌ها اضافه می‌کنی. هنوز آگهی نداری؟ از این استفاده کن: Customer Support Specialist در یک شرکت سفر اینترنتی (دست‌کم دو سال کار با مشتری، انگلیسی نوشتاری خوب، شیفت آخر هفته؛ این شرکت حالا در شش کشور تازه سفر می‌فروشد)."},"model":"I read that your company opened two new clinics in Izmir last year and plans a third. I have worked in patient booking for four years, and I set up the booking system at my last clinic. I am interested in this role because I could help your new clinics get started quickly. That kind of work is exciting for me.","frame":"I read that ___. I have ___ for ___, and I ___. I am interested in this role because I could ___. That kind of work is ___ for me.","words":[{"word":"I read that"},{"word":"interested"},{"word":"exciting"}],"minWords":50,"minSentences":4,"rubric":["Task done: a real fact, a link to you and what you would bring","Organised: the fact first, then you, then what they get","Language: -ed for people, -ing for things; interested in","Tone: real interest in them, no flattery and nothing that fits every company"],"rubricI18n":{"tr":["Görev: gerçek bir bilgi, seninle bağlantısı ve katacağın şey","Düzen: önce bilgi, sonra sen, sonra onların kazancı","Dil: kişiler için -ed, şeyler için -ing; interested in","Üslup: onlara gerçek ilgi; yağcılık yok, her şirkete uyan cümle yok"],"fa":["کامل بودن کار: یک واقعیت، ربطش به تو و چیزی که به آن‌ها اضافه می‌کنی","نظم: اول واقعیت، بعد خودت، بعد چیزی که آن‌ها به دست می‌آورند","زبان: ‎-ed برای آدم‌ها، ‎-ing برای چیزها؛ interested in","لحن: علاقه‌ی واقعی به آن‌ها، بدون تعریف و تمجید و بدون جمله‌ای که برای هر شرکتی درست باشد"]}},"exit":{"id":"c-int-3-x","course":"interview","unit":"int-3","type":"exit","items":[{"from":"int-3","kind":"blank","prompt":"The training video was long and ___, so I stopped it twice.","options":["bored","boring","bore"],"correct":1,"point":2},{"from":"int-3","kind":"blank","prompt":"We were all very ___ about the new office, so we visited it on day one.","options":["excited","exciting","excite"],"correct":0,"point":2},{"from":"int-3","kind":"mcq","prompt":"Which answer to \"Why do you want to work here?\" is strongest?","options":["Your company has a great reputation, and everybody I know says it is a very good place to work.","I read that you are moving into Spain. I sold to Spanish clients for three years, so I could help.","It is near my home, so I could get here quickly every morning and never be late for work."],"correct":1,"point":1},{"from":"int-2","kind":"blank","prompt":"\"Are you free on Monday afternoon?\" \"Yes, I ___.\"","options":["do","am","have"],"correct":1},{"from":"int-2","kind":"mcq","prompt":"You did not understand the word \"relocate\". What do you say?","options":["Sorry, what do you mean by \"relocate\"?","Yes, of course. That is no problem for me.","Relocate is not possible for me, sorry."],"correct":0},{"from":"int-1","kind":"mcq","prompt":"Why should you not memorise every word of your introduction?","options":["It falls apart when someone interrupts you.","Interviewers do not allow notes in the room.","Memorising takes much too long before an interview."],"correct":0}]},"explain":{"id":"c-int-3-e","course":"interview","unit":"int-3","type":"explain","level":"B1","title":{"en":"The first five minutes","tr":"İlk beş dakika","fa":"پنج دقیقه‌ی اول"},"objective":{"en":"After this lesson, you can make small talk and give a real answer to \"Why do you want to work here?\"","tr":"Bu dersin sonunda küçük sohbet edebilecek ve \"Why do you want to work here?\" sorusuna gerçek bir cevap verebileceksin.","fa":"بعد از این درس می‌توانی گپ کوتاه بزنی و به «Why do you want to work here?» جواب واقعی بدهی."},"hook":{"en":"In the first five minutes they begin to picture you as a colleague. So be polite and easy to talk to, and answer \"Why us?\" with a fact that is true only of this company.","tr":"İlk beş dakikada seni bir iş arkadaşı olarak gözlerinde canlandırmaya başlarlar. Bu yüzden kibar ve konuşması kolay biri ol; \"Neden biz?\" sorusunu da yalnızca bu şirket için geçerli bir gerçekle cevapla.","fa":"در پنج دقیقه‌ی اول کم‌کم تو را به‌عنوان همکار تصور می‌کنند. پس مؤدب باش و طوری رفتار کن که راحت بشود با تو حرف زد. به «چرا ما؟» هم با واقعیتی جواب بده که فقط درباره‌ی همین شرکت درست است."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The skill","tr":"Beceri","fa":"مهارت"},"head":{"en":"Three moves for the first five minutes","tr":"İlk beş dakika için üç hamle","fa":"سه کار برای پنج دقیقه‌ی اول"},"steps":[{"en":"Arrive ten minutes early, and be polite to everyone. Reception staff may tell the interviewer what they saw.","tr":"On dakika erken git ve herkese kibar davran. Resepsiyondakiler gördüklerini mülakatçıya anlatabilir.","fa":"ده دقیقه زودتر برو و با همه مؤدب باش. کارکنان پذیرش ممکن است چیزی را که دیده‌اند به مصاحبه‌کننده بگویند.","ex":"Good morning. I'm here for the 10:00 interview."},{"en":"In small talk, answer, add one detail and ask something back. Then it feels like a conversation.","tr":"Küçük sohbette cevapla, bir ayrıntı ekle ve sen de bir soru sor. Böylece gerçek bir sohbete dönüşür.","fa":"در گپ کوتاه جواب بده، یک نکته اضافه کن و تو هم یک سؤال بپرس. این‌طوری گفت‌وگوی واقعی می‌شود.","ex":"Yes, thanks. The map was clear. Have you worked here long?"},{"en":"Before you go, find three facts about them. Without facts, you can't give a real \"Why us?\"","tr":"Gitmeden önce onlarla ilgili üç gerçek bul. Bunlar olmadan \"Neden biz?\" sorusuna inandırıcı bir cevap veremezsin.","fa":"قبل از رفتن سه واقعیت درباره‌ی آن‌ها پیدا کن. بدون این‌ها نمی‌توانی به «چرا ما؟» جواب واقعی بدهی.","ex":"Website, job ad, recent news"},{"en":"For \"Why us?\", give one fact, link it to you, and say what you would bring.","tr":"\"Neden biz?\" için bir gerçek söyle, onu kendine bağla ve katacağın şeyi anlat.","fa":"برای «چرا ما؟» یک واقعیت بگو، آن را به خودت ربط بده و بگو چه چیزی به آن‌ها اضافه می‌کنی.","ex":"I read that... I have... so I could..."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Feelings: -ed or -ing (bored or boring)","tr":"Duygular: -ed mi, -ing mi (bored mu, boring mi)","fa":"احساس‌ها: ‎-ed یا ‎-ing (bored یا boring)"},"steps":[{"en":"-ed: how a person feels.","tr":"-ed: kişinin nasıl hissettiği.","fa":"پسوند ed حسی را نشان می‌دهد که یک آدم دارد.","ex":"I was nervous and a bit confused."},{"en":"-ing: the thing that causes the feeling.","tr":"-ing: duyguya sebep olan şey.","fa":"پسوند ing چیزی را نشان می‌دهد که آن حس را ایجاد می‌کند.","ex":"The question was confusing."},{"en":"\"I'm interesting\" praises you. In an interview, say interested in + the thing you like.","tr":"\"I'm interesting\" kendini övmek olur. Mülakatta interested in + ilgilendiğin şey de.","fa":"جمله‌ی «I'm interesting» یعنی از خودت تعریف می‌کنی. در مصاحبه بگو «I'm interested in» و بعد چیزی را بیاور که به آن علاقه داری.","ex":"I am interested in this role."}],"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["A person feels it: -ed","I was embarrassed. I am interested in this role."],["A thing causes it: -ing","The question was embarrassing. The role is interesting."],["Common pairs","bored / boring, tired / tiring, confused / confusing, excited / exciting"]]},"tip":{"en":"Turkish uses two different words (sıkıldım / sıkıcı), and so does Persian (حوصله‌ام سر رفت / کسل‌کننده). English changes only the ending, so the endings get mixed.","tr":"Türkçede iki ayrı kelime vardır (sıkıldım / sıkıcı). İngilizcede sadece son ek değişir (bored / boring), bu yüzden karışır.","fa":"در فارسی دو عبارت جدا داریم (حوصله‌ام سر رفت / کسل‌کننده). در انگلیسی فقط پسوند عوض می‌شود (bored / boring) و برای همین این دو را با هم اشتباه می‌گیریم."},"wrong":"I am very interesting in this role.","right":"I am very interested in this role."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Safe small talk","tr":"Güvenli küçük sohbet","fa":"گپ کوتاه بی‌خطر"},"body":{"en":"Good topics: the journey, the weather, the building. Avoid politics, religion and money, because they can start a disagreement. Nerves are normal, and you can say so: \"I'm a little nervous, but I'm excited to be here.\"","tr":"İyi konular: yolculuk, hava, bina. Siyaset, din ve para konularına girme; anlaşmazlık çıkarabilirler. Heyecan normaldir ve bunu söyleyebilirsin: \"I'm a little nervous, but I'm excited to be here.\"","fa":"موضوع‌های خوب: مسیر، هوا، ساختمان. سراغ سیاست، دین و پول نرو، چون ممکن است اختلاف نظر پیش بیاید. استرس طبیعی است و می‌توانی بگویی: «I'm a little nervous, but I'm excited to be here.»"},"phrases":[{"phrase":"Yes, thanks. The ... was...","meaning":{"en":"Answers small talk and adds a detail.","tr":"Küçük sohbete cevap verir ve ayrıntı ekler.","fa":"به گپ کوتاه جواب می‌دهد و جزئیات اضافه می‌کند."}},{"phrase":"How about you?","meaning":{"en":"Gives the question back.","tr":"Soruyu karşı tarafa da sorar.","fa":"همان سؤال را از طرف مقابل می‌پرسد."}},{"phrase":"I read that...","meaning":{"en":"Opens your fact about the company.","tr":"Şirketle ilgili bilgini söylemeye başlar.","fa":"حرفت را با واقعیتی درباره‌ی شرکت شروع می‌کند."}},{"phrase":"first impression","meaning":{"en":"What people think of you when they first meet you.","tr":"ilk izlenim.","fa":"اولین برداشت؛ تأثیر اول"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Make \"Why us?\" real","tr":"\"Neden biz?\" cevabını gerçek yap","fa":"«چرا ما؟» را واقعی کن"},"item":"Weak: I want to work here because you are a big and famous company with a good reputation. Your facts: they are opening an office in Izmir; you have worked with clients there for three years.","answer":"I read that you are opening an office in Izmir. I have worked with clients there for three years, so I could help that team from the start.","walk":[{"en":"This fits any big company. Find a fact only they have.","tr":"Bu her büyük şirkete uyar. Yalnızca onlara ait bir gerçek bul.","fa":"این را درباره‌ی هر شرکت بزرگی می‌شود گفت. واقعیتی پیدا کن که فقط درباره‌ی همین شرکت درست است."},{"en":"Link the fact to something you have done. Now it is true only of you.","tr":"Bu gerçeği yaptığın bir şeye bağla. Artık yalnızca senin için geçerli olur.","fa":"این واقعیت را به کاری که کرده‌ای ربط بده. حالا فقط درباره‌ی تو درست است."},{"en":"End with what they get from you.","tr":"Onların senden ne kazanacağıyla bitir.","fa":"با چیزی که از تو به دست می‌آورند تمام کن."}]},"quick":{"prompt":"I am very ___ in this role.","options":["interested","interesting","interest"],"correct":0,"why":{"en":"interested: you feel it, so use -ed. The role itself is interesting.","tr":"interested: bunu sen hissediyorsun, o yüzden -ed. Pozisyonun kendisi interesting olur.","fa":"جواب interested است، چون این حس توست و حس با ed می‌آید. خودِ شغل interesting است."}},"remember":{"en":"If your answer fits every company, it does not answer \"Why us?\" You can now start an interview calmly and give a \"Why us?\" answer that only you could give. Next, you write yours for a real company.","tr":"Cevabın her şirkete uyuyorsa \"Neden biz?\" sorusunu cevaplamıyordur. Artık mülakata sakin başlayabilir ve \"Neden biz?\" sorusuna yalnızca senin verebileceğin bir cevap verebilirsin. Sırada gerçek bir şirket için kendi cevabını yazmak var.","fa":"اگر جوابت برای هر شرکتی درست است، جواب «چرا ما؟» نیست. حالا می‌توانی مصاحبه را آرام شروع کنی و به «چرا ما؟» جوابی بدهی که فقط خودت می‌توانی بدهی. در ادامه جوابت را برای یک شرکت واقعی می‌نویسی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Keeping small talk going: question tags","tr":"Sohbeti sürdürmek: onay soruları (question tags)","fa":"ادامه دادن گپ: question tag"},"steps":[{"en":"Use the helper verb from the statement.","tr":"Cümledeki yardımcı fiili kullan.","fa":"فعل کمکیِ جمله را به کار ببر.","ex":"It's hot today, isn't it?"},{"en":"Positive statement, negative tag, and the other way round.","tr":"Olumlu cümle, olumsuz ek; tersi de geçerli.","fa":"اگر جمله مثبت باشد tag منفی می‌آید و برعکس.","ex":"You aren't from Istanbul, are you?"},{"en":"No helper verb? Use do, does or did.","tr":"Yardımcı fiil yok mu? do, does ya da did kullan.","fa":"فعل کمکی نیست؟ از do، does یا did استفاده کن.","ex":"You found us easily, didn't you?"}],"table":{"headers":{"en":["Statement","Tag"],"tr":["Cümle","Ek"],"fa":["جمله","tag"]},"rows":[["Positive statement, negative tag","It's a nice building, isn't it?"],["Negative statement, positive tag","You aren't from Istanbul, are you?"],["No helper verb: do / does / did","You found the office, didn't you?"]]},"body":{"en":"B2: in the small talk, use one question tag to keep the conversation going.","tr":"B2: küçük sohbette konuşmayı sürdürmek için bir question tag kullan.","fa":"در مسیر B2: در گپ کوتاه، برای ادامه دادن حرف یک question tag به کار ببر."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
